import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const E=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/CTABLES-Data-Summarization.md","filePath":"manual-zh/CTABLES-Data-Summarization.md","lastUpdated":1785684581000}'),o={name:"manual-zh/CTABLES-Data-Summarization.md"};function h(n,t,l,p,m,i){return r(),e("div",null,[...t[0]||(t[0]=[a(`<h4 id="_15-7-2-数据汇总" tabindex="-1">15.7.2 数据汇总 <a class="header-anchor" href="#_15-7-2-数据汇总" aria-label="Permalink to &quot;15.7.2 数据汇总&quot;">​</a></h4><p><code>CTABLES</code> 命令允许用户通过 <em>summary specifications</em>（汇总说明）来控制数据的汇总方式，该语法在 <code>TABLE</code> 子命令中变量名之后的方括号内列出一个或多个汇总函数名（可选以逗号分隔）。当所有变量都是分类变量时，可以为任一轴上最内层嵌套的变量给出汇总说明。当存在标量变量时，只有标量变量可以有汇总说明。</p><p>以下示例包含分类变量的列百分比和行百分比汇总说明，以及标量变量的均值和中位数：</p><pre><code>CTABLES
    /TABLE=age [MEAN, MEDIAN] BY gender
    /TABLE=ageGroup [COLPCT, ROWPCT] BY gender.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Column %</th><th>Row %</th><th>Column %</th><th>Row %</th></tr></thead><tbody><tr><td></td><td>S3a. GENDER:</td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>Male</td><td>Female</td><td></td><td></td><td></td></tr><tr><td></td><td>Mean</td><td>Median</td><td>Mean</td><td>Median</td><td></td></tr><tr><td>D1. AGE: What is your age?</td><td>46</td><td>45</td><td>50</td><td>52</td><td></td></tr><tr><td></td><td></td><td>S3a. GENDER:</td><td></td><td></td><td></td></tr><tr><td></td><td></td><td>Male</td><td>Female</td><td></td><td></td></tr><tr><td>Age group</td><td>15 or younger</td><td>.0%</td><td>.</td><td>.0%</td><td>.</td></tr><tr><td>16 to 25</td><td>19.0%</td><td>54.0%</td><td>13.1%</td><td>46.0%</td><td></td></tr><tr><td>26 to 35</td><td>15.2%</td><td>49.2%</td><td>12.7%</td><td>50.8%</td><td></td></tr><tr><td>36 to 45</td><td>15.6%</td><td>47.2%</td><td>14.2%</td><td>52.8%</td><td></td></tr><tr><td>46 to 55</td><td>16.8%</td><td>44.8%</td><td>16.8%</td><td>55.2%</td><td></td></tr><tr><td>56 to 65</td><td>16.5%</td><td>41.4%</td><td>18.9%</td><td>58.6%</td><td></td></tr><tr><td>66 or older</td><td>17.0%</td><td>36.0%</td><td>24.4%</td><td>64.0%</td><td></td></tr></tbody></table><p>汇总说明可以通过在汇总函数名后附加字符串或格式说明（或两者，按此顺序）来覆盖默认标签和格式。例如：</p><pre><code>CTABLES /TABLE=ageGroup [COLPCT &#39;Gender %&#39; PCT5.0,
                         ROWPCT &#39;Age Group %&#39; PCT5.0]
               BY gender.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Gender %</th><th>Age Group %</th><th>Gender %</th><th>Age Group %</th></tr></thead><tbody><tr><td></td><td></td><td>S3a. GENDER:</td><td></td><td></td><td></td></tr><tr><td></td><td></td><td>Male</td><td>Female</td><td></td><td></td></tr><tr><td>Age group</td><td>15 or younger</td><td>0%</td><td>.</td><td>0%</td><td>.</td></tr><tr><td>16 to 25</td><td>19%</td><td>54%</td><td>13%</td><td>46%</td><td></td></tr><tr><td>26 to 35</td><td>15%</td><td>49%</td><td>13%</td><td>51%</td><td></td></tr><tr><td>36 to 45</td><td>16%</td><td>47%</td><td>14%</td><td>53%</td><td></td></tr><tr><td>46 to 55</td><td>17%</td><td>45%</td><td>17%</td><td>55%</td><td></td></tr><tr><td>56 to 65</td><td>16%</td><td>41%</td><td>19%</td><td>59%</td><td></td></tr><tr><td>66 or older</td><td>17%</td><td>36%</td><td>24%</td><td>64%</td><td></td></tr></tbody></table><p>除标准格式外，<code>CTABLES</code> 还允许用户指定以下特殊格式：</p><table tabindex="0"><thead><tr><th>NEGPAREN w . d</th><th>将负数括在括号中。</th><th>42.96</th><th>(42.96)</th></tr></thead><tbody><tr><td>NEQUAL w . d</td><td>添加 N= 前缀。</td><td>N=42.96</td><td>N=-42.96</td></tr><tr><td>PAREN w . d</td><td>将所有数字括在括号中。</td><td>(42.96)</td><td>(-42.96)</td></tr><tr><td>PCTPAREN w . d</td><td>将所有数字括在括号中，并带 ‘ % ’ 后缀。</td><td>(42.96%)</td><td>(-42.96%)</td></tr></tbody></table><p>括号提供了一种简写方式，可将汇总说明应用于多个变量。例如，以下两个命令：</p><pre><code>CTABLES /TABLE=ageGroup[COLPCT] + membersOver16[COLPCT] BY gender.
CTABLES /TABLE=(ageGroup + membersOver16)[COLPCT] BY gender.
</code></pre><p>产生如下所示的相同输出：</p><table tabindex="0"><thead><tr><th></th><th></th><th>Male</th><th>Female</th></tr></thead><tbody><tr><td></td><td></td><td>S3a. GENDER:</td><td></td></tr><tr><td></td><td></td><td>Column %</td><td>Column %</td></tr><tr><td>Age group</td><td>15 or younger</td><td>.0%</td><td>.0%</td></tr><tr><td>16 to 25</td><td>19.0%</td><td>13.1%</td><td></td></tr><tr><td>26 to 35</td><td>15.2%</td><td>12.7%</td><td></td></tr><tr><td>36 to 45</td><td>15.6%</td><td>14.2%</td><td></td></tr><tr><td>46 to 55</td><td>16.8%</td><td>16.8%</td><td></td></tr><tr><td>56 to 65</td><td>16.5%</td><td>18.9%</td><td></td></tr><tr><td>66 or older</td><td>17.0%</td><td>24.4%</td><td></td></tr><tr><td>S1. Including yourself, how many members of this household are age 16 or older?</td><td>None</td><td>.0%</td><td>.0%</td></tr><tr><td>1</td><td>21.4%</td><td>35.0%</td><td></td></tr><tr><td>2</td><td>61.9%</td><td>52.3%</td><td></td></tr><tr><td>3</td><td>11.0%</td><td>8.2%</td><td></td></tr><tr><td>4</td><td>4.2%</td><td>3.2%</td><td></td></tr><tr><td>5</td><td>1.1%</td><td>.9%</td><td></td></tr><tr><td>6 or more</td><td>.4%</td><td>.4%</td><td></td></tr></tbody></table><p>以下各节列出了可用的汇总函数。每个函数名之后给出其默认标签和格式。如果未列出格式，则默认格式为被汇总变量的打印格式。</p><table tabindex="0"><thead><tr><th>• 单个单元格的汇总函数</th><th></th><th></th></tr></thead><tbody><tr><td>• 单元格组的汇总函数</td><td></td><td></td></tr><tr><td>• 调整权重的汇总函数</td><td></td><td></td></tr><tr><td>• 非加权汇总函数</td><td></td><td></td></tr></tbody></table>`,16)])])}const A=d(o,[["render",h]]);export{E as __pageData,A as default};
